#pragma once
#include "kstationVoiceUpdateTask.h"
#include "kstationMidiEventTask.h"
#include <optional>
namespace kstation {
class ControllerVoiceSourceSequence final {
 using A=VoiceParameterSourceTask;using AS=A::Stage;using M=VoiceParameterModeTask;using MS=M::Stage;using E=VoiceParameterLongEnvelopeTask;using ES=E::Stage;using F=MidiFloatConvertTask;using FS=F::Stage;
public:
 explicit ControllerVoiceSourceSequence(uint32_t patch):patch_(patch){source_.emplace(patch,0);}bool complete()const{return stage_==6;}bool awaitingDsp()const{return source_?source_->child()==A::Child::Dsp:mode_?mode_->awaitingDsp():env_&&env_->child()==E::Child::Dsp;}uint32_t word()const{return source_?source_->word():mode_?mode_->word():env_->word();}bool resumeDsp(){if(!awaitingDsp())return false;bool ok=source_?source_->resumeChild():mode_?mode_->resumeDsp():env_->resumeChild();if(ok)selectNext();return ok;}
 bool stackWrites()const{if(floating_)return false;if(source_){auto s=source_->stage();return s==AS::PushFloat||s==AS::DispatchTableFirst||s==AS::DispatchTableSecond||s==AS::DispatchFloat||s==AS::DispatchFloatFirst||s==AS::DispatchFloatSecond;}if(mode_){auto s=mode_->stage();return s==MS::Push||s==MS::DispatchFirst||s==MS::DispatchSecond;}return env_->stage()==ES::DispatchFloat||env_->stage()==ES::DispatchDsp;}
 unsigned nextClocks()const{if(complete())return 0;if(floating_){switch(floating_->stage()){case FS::Complete:return 0;case FS::CompareMinimum:return 6;case FS::Return:return 7;default:return 3;}}uint32_t a=0;unsigned width=0;access(a,width);if(source_){auto s=source_->stage();A::Credits c{(s==AS::PushFloat||s==AS::PopScale)?1u:width?bus(a,width):0,10};return source_->nextClocks(c);}if(mode_){auto s=mode_->stage();M::Credits c{(s==MS::Push||s==MS::Pop)?1u:width?bus(a,width):0,10};return mode_->nextClocks(c);}E::Credits c{width?bus(a,width):0,10};return env_->nextClocks(c);}
 template<class R>unsigned advanceBefore(unsigned budget,R&&read){auto cost=nextClocks();if(!cost||cost>budget)return 0;if(floating_){if(!floating_->advance())return 0;if(floating_->complete()){auto v=floating_->result();floating_.reset();if(source_)source_->resumeChild(v);else env_->resumeChild(v);}return cost;}uint32_t a=0;unsigned width=0;access(a,width);if(source_){auto s=source_->stage();A::Credits c{(s==AS::PushFloat||s==AS::PopScale)?1u:width?bus(a,width):0,10};auto used=source_->advanceBefore(cost,c,[&](A::Read f){if(f==A::Read::Stack)return uint32_t(saved_)<<8;auto v=read(a&0xffffff,width,cost);if(f==A::Read::Float)saved_=uint8_t(v);return v;});if(source_->child()==A::Child::Float)floating_.emplace(source_->input());selectNext();return used;}if(mode_){auto s=mode_->stage();M::Credits c{(s==MS::Push||s==MS::Pop)?1u:width?bus(a,width):0,10};auto used=mode_->advanceBefore(cost,c,[&](){if(s==MS::Pop)return uint32_t(saved_);auto v=read(a&0xffffff,width,cost);saved_=uint8_t(v);return v;});selectNext();return used;}E::Credits c{width?bus(a,width):0,10};auto used=env_->advanceBefore(cost,c,[&](bool){return read(a&0xffffff,width,cost);});if(env_->child()==E::Child::Float)floating_.emplace(env_->input());selectNext();return used;}
private:
 void selectNext(){if(source_&&source_->complete()){source_.reset();++stage_;}else if(mode_&&mode_->complete()){mode_.reset();++stage_;}else if(env_&&env_->complete()){env_.reset();++stage_;}else return;switch(stage_){case 1:mode_.emplace(patch_,0);break;case 2:env_.emplace(patch_,0);break;case 3:source_.emplace(patch_,1);break;case 4:mode_.emplace(patch_,1);break;case 5:env_.emplace(patch_,1);break;default:break;}}
 static unsigned bus(uint32_t a,unsigned n){int p=-1;unsigned c=0;for(unsigned i=0;i<n;++i){auto x=(a+i)&0xffffff;if(x<0x400000||(x>=0xfffd10&&x<0xffffa0)){if((p&1)||x!=uint32_t(p|1))c+=x<0x400000?3:1;p=int(x);}else{c+=x>=0xffffa0?1:3;p=-1;}}return c;}void access(uint32_t&a,unsigned&w)const{if(source_){switch(source_->stage()){case AS::ReadMode:a=patch_+0x49+3*source_->lane();w=1;break;case AS::ReadFloat:a=patch_+0x48+3*source_->lane();w=1;break;case AS::ReadTable:a=source_->tableAddress();w=4;break;default:break;}}else if(mode_){if(mode_->stage()==MS::Read){a=mode_->address();w=1;}}else if(env_){switch(env_->stage()){case ES::ReadValue:a=env_->valueAddress();w=1;break;case ES::ReadOffset:a=env_->offsetAddress();w=2;break;default:break;}}}
 uint32_t patch_;unsigned stage_=0;uint8_t saved_=0;std::optional<A>source_{};std::optional<M>mode_{};std::optional<E>env_{};std::optional<F>floating_{};
};
}
